// ActWords shares action-summary vocabulary across the supported reader languages.
func ActWords(language textlang.Lang, family string) map[string]string {
	out := map[string]string{}
	prefix := "act." + family + "."
	for code, definition := range actDefinitions {
		if key, ok := strings.CutPrefix(code, prefix); ok {
			out[key] = definition.Words.In(language)
		}
	}
	return out
}
